head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > P > textAlign]<br/>컴포넌트의 아이템 리스트와 라벨 표시 영역의 텍스트 정렬을 설정합니다.",
    "validation" : [
        "미설정 시 아이템의 라벨이 가운데 정렬로 표시됩니다.",
        "left 설정 시 아이템의 라벨이 왼쪽 정렬로 표시됩니다.",
        "center 설정 시 아이템의 라벨이 가운데 정렬로 표시됩니다.",
        "right 설정 시 아이템의 라벨이 오른쪽 정렬로 표시됩니다.",
        "renderType=native,select 인 경우 select 태그의 style 속성에 'text-align' 값이 설정됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {     
        renderType : con_renderType.getText(),
        textAlign : con_textAlign.getText(),
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createLabel('label="renderType 이 select, native 인 경우는 selectbox 의 text-align 값만 있고 아이템의 text-align 값은 없음"', '', 'label1');
    $c.gcm.createBasicSelectBox(cList);
}



scwin.btn_getTextAlign_onclick = function (e) {
    let comp = "target1";
    let renderType = con_renderType.getText();

    if (renderType == "" || renderType == "component" || renderType == "auto") {
        let targetElements = document.querySelectorAll('[id*='+comp+']');
        let divs = targetElements[0].querySelectorAll('.w2selectbox_label');

        divs.forEach((div) => {
            let textAlign = div.style.textAlign;

            if (!textAlign) {
                let computedStyle = window.getComputedStyle(div);
                textAlign = computedStyle.textAlign;
            }
            wf_body_bottom.getObj("scwin").setReturnValue("selectbox textAlign : " + textAlign);
        });

        comp = "target1_itemTable";
        targetElements = document.querySelectorAll('[id*='+comp+']');   

        if (targetElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("SelectBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

        let tds = targetElements[0].querySelectorAll('.w2table_sb_col');

        tds.forEach((td) => {            
            let textAlign = td.style.textAlign;

            if (!textAlign) {
                let computedStyle = window.getComputedStyle(td);
                textAlign = computedStyle.textAlign;
            }
            wf_body_bottom.getObj("scwin").setReturnValue("item textAlign : " + textAlign);
        });
    }
    else if (renderType == "native") {
        let targetElements = document.querySelectorAll('[id*='+comp+']');
        let selects = targetElements[0].querySelectorAll('.w2selectbox_native_select');
        let textAlign = selects[0].style.textAlign;

        wf_body_bottom.getObj("scwin").setReturnValue("selectbox textAlign : " + textAlign);
    }
    else {
        let targetElements = document.querySelectorAll('[id*='+comp+']');
        let textAlign = targetElements[0].style.textAlign;

        wf_body_bottom.getObj("scwin").setReturnValue("selectbox textAlign : " + textAlign);        
    }
};
